const now = $now.setZone('Asia/Manila');
return [{
  json: {
    StaffName: body.staffName,
    Day: now.toFormat('cccc'),
    Date: now.toFormat('yyyy-MM-dd'),
    Time: now.toFormat('hh:mm a'),
    Ts: now.toUTC().toFormat('yyyy-MM-dd HH:mm:ss')
  }
}];

const rows = $input.all().map(i => i.json).filter(r => r.id);
const shifts = rows.map(r => ({
  id: r.id,
  staffName: r.staff_name,
  dayIn: r.day_in,
  dateIn: r.date_in,
  timeIn: r.time_in,
  dayOut: r.day_out,
  dateOut: r.date_out,
  timeOut: r.time_out,
  status: r.status,
  orderCount: Number(r.order_count) || 0,
  totalSales: Number(r.total_sales) || 0,
  totalProfit: Number(r.total_profit) || 0
}));
return [{ json: { success: true, count: shifts.length, shifts } }];
